# Find nSamples, nPatches where allocation size is between 524272 and 5,000,000
# and nSamples*nPatches is large (so we can write many items)
results = []
for ns in range(0x7ffe, 1000, -1):
    for np in range(0x7ffe, 1000, -1):
        alloc = ((ns+1)*(np+1)*8) & 0xFFFFFFFF
        if 524272 < alloc < 5000000:
            results.append((alloc, ns, np, ns*np))
            if len(results) > 10:
                break
    if len(results) > 10:
        break
for r in results:
    print(r)
